{"command": "@'
import re
from pathlib import Path

def names(path):
    out = {}
    for line in Path(path).read_text(encoding="utf-8").splitlines():
        m = re.match(r"^([A-Za-z0-9_.\-]+)==([^\s]+)", line)
        if m:
            out[m.group(1).lower()] = m.group(2)
    return out

runtime = names("requirements.lock")
dev = names("requirements-dev.lock")
print("runtime:", len(runtime), "dev:", len(dev))
missing = {k: v for k, v in runtime.items() if k not in dev}
print("missing in dev:", missing)
diff = {k: (v, dev[k]) for k, v in runtime.items() if k in dev and dev[k] != v}
print("version mismatch:", diff)
'@ | .\.venv\Scripts\python.exe -", "description": "Compare runtime and dev lock contents", "workdir": "simorph"}

