import json, urllib.request, urllib.error

def get(url, raw=False):
    req = urllib.request.Request(url, headers={"Accept": "application/vnd.github+json", "User-Agent": "simorph-check"})
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            data = r.read()
            return r.status, data if raw else json.loads(data)
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode("utf-8", "replace")[:300]
    except Exception as e:
        return None, repr(e)

st, runs = get("https://api.github.com/repos/Rfne/simorph/actions/runs?per_page=5")
print("runs status", st, "total", runs.get("total_count") if isinstance(runs, dict) else "")
for run in (runs.get("workflow_runs") or []):
    print("RUN", run["id"], run["head_sha"][:9], run["name"], run["event"], run["status"], run["conclusion"], run["created_at"], run["html_url"])
    st2, jobs = get(run["jobs_url"] + "?per_page=20")
    if isinstance(jobs, dict):
        for j in jobs.get("jobs", []):
            print("   JOB", j["id"], j["name"], j["status"], j["conclusion"], j["runner_name"] or j.get("labels"))
            for s in j.get("steps", []):
                print("      STEP", s["number"], s["name"], s["status"], s["conclusion"])
    else:
        print("   jobs error:", jobs)
'@ | .\.venv\Scripts\python.exe -", "description": "Fetch CI runs and job steps from GitHub API", "timeout": 300, "workdir": "simorph"}

