{"command": "@'
import subprocess, sys, tomllib
from packaging.requirements import Requirement

def show(path):
    return subprocess.run(["git", "show", f"HEAD:{path}"], capture_output=True, text=True, encoding="utf-8").stdout

pyproject = tomllib.loads(show("pyproject.toml"))
deps = pyproject["project"]["dependencies"]
lock_lines = [l.strip() for l in show("requirements-dev.lock").splitlines() if l.strip() and not l.strip().startswith("#")]
locked = {}
for line in lock_lines:
    try:
        r = Requirement(line)
    except Exception:
        continue
    if r.specifier and len(r.specifier) == 1 and list(r.specifier)[0].operator == "==":
        locked[r.name.lower()] = str(list(r.specifier)[0].version)

print("deps in pyproject:", len(deps))
unmet = []
for d in deps:
    r = Requirement(d)
    if r.marker is not None and not r.marker.evaluate():
        continue
    have = locked.get(r.name.lower())
    if have is None:
        unmet.append((r.name, str(r.specifier), "NOT IN LOCK"))
    elif r.specifier and not r.specifier.contains(have, prereleases=True):
        unmet.append((r.name, str(r.specifier), have))
print("unmet at HEAD:", unmet)
print("local lock has pyarrow:", "pyarrow" in open("requirements-dev.lock", encoding="utf-8").read().lower())
'@ | .\.venv\Scripts\python.exe -", "description": "Compare pyproject deps with HEAD lock file", "timeout": 300, "workdir": "simorph"}

